INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (301833,'ruRU','','Что-то не так... Почему нет взрыва?',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (301834,'ruRU','Взрыва не будет. Я дал тебе нерабочий детонатор.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (301835,'ruRU','','Что? Почему?',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (301836,'ruRU','Теперь этим займется ШРУ. Освобожденная у Братства Справедливости кузня и корабль обладают стратегической важностью. Мы берем их под свой контроль.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (301837,'ruRU','','Ты не понимаешь. Эта кузня отравляет фермы Западного Края! Если ее не уничтожить, тут несколько поколений ничего не будет расти. Народ останется без пищи!',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (301838,'ruRU','Благодарю за беспокойство, эльф, но теперь это внутреннее дело Штормграда. Твоя помощь больше не нужна.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (302214,'ruRU','Чтобы описать всю картину, требуется время. У тебя оно вряд ли есть, поэтому постараюсь покороче.\r\n\r\nЕсли простыми словами, кристаллы – это якоря. С их помощью можно навечно, или пока кристаллы не будут уничтожены, привязать предмет, существо или даже место к нашему миру. Принц Тортелдрин приказал возвести подобные пилоны, когда решил заточить демона Бессмер\'тера. Некоторые из шен\'дралар попытались возразить и предложили разумную альтернативу, но принц не желал слушать доводы и подавлял несогласие.\r\n\r\nЯ успел изучить устройство тех пилонов, прежде чем в городе стало небезопасно и мне пришлось спешно возвращаться в Шен\'дралас.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (302215,'ruRU','Предложенная альтернатива противоречила замыслам, которые Тортелдрин уже начал приводить в исполнение. Учитывая, что он имел дело с силами, не лучшим образом влияющими на рассудок, неудивительно, что его ответом была агрессия.\r\n\r\nПочти все, кто выступил против призыва и подчинения демона, были убиты в тот же день. Кому-то удалось бежать, включая моих родственников, которые не поддерживали планы принца. Но даже спустя тысячи лет я так и не встретил других выживших после этого раскола.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (305021,'ruRU','С виду я бы не сказал, но нутром чую, что лучше послушаться. Наверно, я просто посижу тут еще немного. Спасибо, хорошо поболтали.','С виду я бы не сказал, но нутром чую, что лучше послушаться. Наверно, я просто посижу тут еще немного. Спасибо, хорошо поболтали.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (307136,'ruRU','Когда-то Шен\'дралас был частью Эльдре\'Таласа – древнего города моего народа, расположенного за южными горами. Кажется, теперь его называют Забытый город. Быть может, тебе приходилось о нем слышать.\r\n\r\nСо временем силы природы сточили камень тех прекрасных зданий и погубили наши сады. Мне бы ужасно хотелось вновь пройтись по залам Эльдре\'Таласа, но меня все еще мучают воспоминания о прошлом.\r\n\r\nПока я довольствуюсь тем, что присматриваю за этими землями и вспоминаю о былом.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (311268,'ruRU','Через горную гряду на северо-востоке Азшары прямо на север от руин Эльдарата пролегает путь, ведущий в сердце крепости Черночревов.','Через горную гряду на северо-востоке Азшары прямо на север от руин Эльдарата пролегает путь, ведущий в сердце крепости Черночревов.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (311269,'ruRU','Племя Черночревов считает эту крепость своим домом. Если отправишься на север Азшары, будь начеку: племя не доверяет чужакам. Видя, как мы расправляемся с их оскверненными сородичами, Черночревы отвечают нам той же агрессией, чтобы обезопасить себя.','Племя Черночревов считает эту крепость своим домом. Если отправишься на север Азшары, будь начеку: племя не доверяет чужакам. Видя, как мы расправляемся с их оскверненными сородичами, Черночревы отвечают нам той же агрессией, чтобы обезопасить себя.',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (313610,'ruRU','Соглашусь. Хотя наш народ объединился, чтобы пережить Великий Раскол, город все равно был обречен. Кто бы мог подумать, что к его гибели приведет такая банальная вещь, как внутренние распри?\r\n\r\nВ те времена я верой и правдой служил принцу Тортелдрину, но за прошедшие годы я осознал, что по-настоящему мы потеряли его, как только началось восстание. Все, что случилось после этого, – лишь последствия раны в его душе.\r\n\r\nЯ стараюсь не думать о прошлом... в особенности о моей роли в событиях тех времен.\r\n\r\nСтараюсь... но воспоминания все еще терзают меня.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (313613,'ruRU','Радоваться жизни на краю братской могилы моих сородичей... чистый эгоизм. Многие из моего ордена все еще укрываются в покоях принца Тортелдрина. Должно быть, прячутся от чувства вины. Глядя на город с этой стороны, я просто не могу игнорировать горькую правду.\r\n\r\nЯ по-прежнему причисляю себя к шен\'дралар, но уже очень давно не бывал в библиотеке, где когда-то проводил все свои дни.','',71037);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES (329343,'ruRU','Дикие тролли, населяющие многочисленные острова Южных морей, известны своей жестокостью и склонностью к мрачным ритуалам.','',71037);
